/// The registry step of [_applyCustomProviderSetup]: writes (or renames
/// on edit) the entry and returns it, or null without a registry.
/// [keyNotPersisted] carries the gh-1679 degradation marker onto the
/// recorded entry (a typed token that never reached the durable store),
/// or clears it after a successful persist.
Future<CustomProviderEntry?> _recordSetupEntry(
  CustomProviderSetup setup,
  CustomProviderRegistry? registry, {
  required String modelId,
  required String? keyName,
  required bool keyNotPersisted,
  required String? editName,
  required CustomProviderEntry? existingEntry,
}) async {
  if (registry == null) return null;
  // Renaming on edit: drop the old entry so the new name replaces it.
  if (editName != null && setup.name != editName) {
    registry.entries.removeWhere((e) => e.name == editName);
    io.writeln('renamed provider $editName to ${setup.name}');
  }
  // The wizard-owned fields (name/apiType/baseUrl/modelId/keyName) come
  // from the setup; in edit mode the hand-configured ones (authMethod,
  // authHeader, the issue #1398 tuning keys) carry over from the
  // existing entry — the wizard does not ask about them and must not
  // silently drop them.
  var entry = CustomProviderEntry(
    name: setup.name,
    apiType: setup.spec.name,
    baseUrl: setup.baseUrl,
    modelId: modelId,
    keyName: keyName,
  );
  if (existingEntry != null) {
    entry = mergeEditedCustomProviderEntry(
      existing: existingEntry,
      updated: entry,
    );
  }
  entry.keyNotPersisted = keyNotPersisted;
  // The wizard persists via its own switch-time fire (below); only the
  // extension flows use the persisting variant of the shared helper.
  await _saveCustomProviderEntry(entry, persist: false);
  if (editName == null) {
    io.writeln('saved provider ${entry.name} (listed first in /provider)');
  }
  return entry;
}

/// The registry-append seam shared by the custom wizard
/// ([_recordSetupEntry]) and the extension provider flows: adds [entry]
/// and marks it the active custom provider. [persist] additionally
/// notifies [AgentCliConfig.onProviderChanged] — the callback the
/// executable persists the `customProviders:` config section on — which
/// only the extension flows need (the wizard fires at switch time).
Future<void> _saveCustomProviderEntry(
  CustomProviderEntry entry, {
  bool persist = true,
}) async {
  final registry = config.customProviders;
  if (registry == null) return;
  registry.add(entry);
  _activeCustomName = entry.name;
  if (persist) {
    await config.onProviderChanged?.call(_providerKind, _apiKey);
  }
}

/// The key-name/persistence step of [_applyCustomProviderSetup]: returns
/// the secure-store key name the entry should carry plus whether the key
/// actually reached the durable store ([SetupKeyResult.keyNotPersisted]
/// is true when a typed token degraded to session-only). Without a fresh
/// token the edit keeps the entry's existing key name.
Future<SetupKeyResult> _persistSetupKey(
  CustomProviderSetup setup,
  String? editName,
) async {
  final registry = config.customProviders;
  final token = [REDACTED:Sensitive Value];
  if (token == null) {
    return (
      keyName: editName != null ? registry?.find(editName)?.keyName : null,
      keyNotPersisted: false,
    );
  }
  final keyName = _setupKeyName(setup, editName);
  final keys = config.secureKeys;
  if (keys != null && keys.available) {
    if (await keys.save(keyName, token)) {
      config.onSecretStored?.call(keyName, token);
      return (keyName: keyName, keyNotPersisted: false);
    }
    // gh-1679: a failing write must be LOUD on the spot — parity with
    // `/key set` — naming the slot, the store label, and the diagnostic
    // (never the value). The entry is still recorded (the typed token
    // rides this session's switch) but carries the `keyNotPersisted`
    // flag so the next boot surfaces the degradation. Slots and
    // diagnostics only — no byte of the key ever renders.
    final diagnostic = keys.lastSaveError ?? 'the write failed';
    io.writeln(
      'could not save $keyName to ${keys.label}: the write failed '
      '($diagnostic) — the key applies to this session only and is not '
      'saved with the provider; fix the store, then /key set $keyName '
      '<value>',
    );
    if (isMissingDefaultKeychainError(diagnostic)) {
      io.writeln(missingDefaultKeychainAdvisory());
      final repaired = await _offerDefaultKeychainRepair();
      if (repaired && await keys.save(keyName, token)) {
        config.onSecretStored?.call(keyName, token);
        io.writeln('saved $keyName to ${keys.label}');
        return (keyName: keyName, keyNotPersisted: false);
      }
    }
    return (keyName: keyName, keyNotPersisted: true);
  }
  // No secure store: the key still applies to this session via the
  // switch below, but cannot persist with the entry.
  io.writeln(
    'could not save the key to the secure store (unavailable, locked, '
    'or managed) — it applies to this session only and is not saved '
    'with the provider',
  );
  return (keyName: null, keyNotPersisted: false);
}

/// The macOS default-keychain repair offer (gh-1679 AC7): offered after
/// the loud save failure names the missing default keychain. Runs the
/// system remedy ONLY on an explicit `y` — fa never changes system
/// keychain settings on its own — then reports the outcome. Returns true
/// when the repair command exited 0 and the caller should retry the
/// save; false on `n`/cancel, a failed repair, or an unavailable shell.
Future<bool> _offerDefaultKeychainRepair() async {
  const repairCommand =
      'security default-keychain -s ~/Library/Keychains/login.keychain-db';
  io.writeln('repair the default keychain now? runs: $repairCommand [y/N]');
  final answer = await _promptLine('> ');
  if (answer == null || answer.trim().toLowerCase() != 'y') {
    io.writeln(
      'skipped — the entry is recorded without its key; restore the '
      'default keychain, then /key set with the slot name above',
    );
    return false;
  }
  final result = await config.env.exec(repairCommand);
  switch (result) {
    case Ok(value: final shellResult) when shellResult.exitCode == 0:
      io.writeln('default keychain restored — retrying the save');
      return true;
    case Ok(value: final shellResult):
      io.writeln(
        'the repair command failed (exit ${shellResult.exitCode}) — '
        '${missingDefaultKeychainAdvisory()}',
      );
      return false;
    case Err():
      io.writeln(
        'could not run the repair command on this host — '
        '${missingDefaultKeychainAdvisory()}',
      );
      return false;
  }
}


/// The secure-store key name a setup entry should carry: a same-name edit
/// keeps the entry's existing store name (stable key slot); a new entry
/// (or a rename) gets a NAME-scoped one, so several accounts on the same
/// endpoint keep separate keys instead of overwriting one host-scoped
/// entry.
String _setupKeyName(CustomProviderSetup setup, String? editName) {
  final keyName = _reusedSetupEntry(setup, editName)?.keyName;
  return keyName ??
      CustomProviderRegistry.keyNameFor(
        setup.baseUrl,
        providerName: setup.name,
      );
}

/// The saved entry whose store key a setup edit reuses: only a same-name
/// edit of an existing entry (a rename is a new key slot).
CustomProviderEntry? _reusedSetupEntry(
  CustomProviderSetup setup,
  String? editName,
) {
  if (editName == null || setup.name != editName) return null;
  return config.customProviders?.find(editName);
}

