content.text:
/// YOLO rm false-positive e2e (issue #460 AC4):
///
/// Boots the real CLI as a subprocess against the mock LLM with
/// `approvalMode: yolo` and scripts one bash tool call per run:
///
/// - `rm -f /tmp/…` (the owner's false-positive shape) must EXECUTE: no
///   critical dialog, no denial, run completes normally.
/// - `rm -rf /` (the canonical catastrophe) must still trip the critical
///   interceptor. Headless has no approval UI, so the forced prompt denies
///   the call and the denial reason reaches the model as the tool result.
@TestOn('vm')
@Tags(['integration'])
@Timeout(Duration(minutes: 5))
library;

import 'dart:convert';
import 'dart:io';

import 'package:test/test.dart';

import 'package:fa_llm_mock/fa_llm_mock.dart';

import 'pty_harness.dart';

void main() {
  late Directory tempHome;
  late Directory workspace;

  setUp(() {
    tempHome = Directory.systemTemp.createTempSync('yolo_rm_home_');
    File('${tempHome.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('approvalMode: yolo\n');
    workspace = Directory.systemTemp.createTempSync('yolo_rm_ws_');
  });

  tearDown(() {
    tempHome.deleteSync(recursive: true);
    workspace.deleteSync(recursive: true);
  });
1:tags:
2-  integration:
3-    # Integration tests spawn real processes / network and are excluded from the
4-    # pre-commit gate. Run them manually with: dart test --tags integration
5-  browser-ext:
6-    # Headless-Chrome extension suite (test/browser_ext/). CI runs it only
7-    # through the dedicated browser-ext.yml workflow (builds sw/agent.js and
8-    # supplies Chrome for Testing); ci.yml's tag job excludes it:
9-    # dart test --tags integration --exclude-tags browser-ext
10-  llm:
11-    # Real-provider smoke tests (issue #551): hit live provider APIs and need
12-    # secrets. They carry `integration` too and run ONLY in the tag-only
13-    # provider-smoke job (v* tags) and nightly — every per-PR suite excludes
14-    # them: dart test --exclude-tags llm
15-    #
16-    # gh-1199: the boundary is now enforced at the gate's integration shard
17-    # SELECTION too (shard_files.py --exclude-tag llm, asserted by
18-    # test/scripts/shard_files_llm_boundary_test.dart) and by
19-    # scripts/check_llm_tag_boundary.py — a live-looking integration file
20-    # without this tag fails the static gate. See docs/live-llm-testing.md.
21-    #

